mapper.select:
SELECT TAB.* FROM ( SELECT lcc.credit_contract_id, lcc.company_id, lcc.document_type, lcc.document_category, lcc.business_type, lcc.credit_contract_number,quotaTypeN lcc.credit_contract_name, lcc.credit_contract_status, lcc.credit_line_id, lcc.credit_bp_id, lcc.description, lcc.created_by, lcc.creation_date, lcc.last_updated_by, lcc.last_update_date, lcc.lon_company_id, lcc.financing_channel, lcc.credit_con_number, lcc.credit_reply_no, lcc.credit_category, lcc.channel_business_flag, lcc.ref_credit_bp_id, lcc.data_class, lcc.confirm_status, lcc.last_change_req_id, lcc.credit_line_amt, nvl(calc.credit_exposure_amt, 0) credit_exposure_amt, nvl(calc.credit_unexposure_amt, 0) credit_unexposure_amt, nvl(calc.withdraw_balance, 0) withdraw_balance_sum, nvl(calc.actual_available_amt,0) actual_available_amt_sum, nvl(calc.total_withdraw_amount,0) total_withdraw_amount_sum, nvl(calc.limit_withdraw_amount,0) limit_withdraw_amount_sum, (nvl(lcc.credit_line_amt,0) - nvl(calc.credit_exposure_amt, 0)) open_to_buy, lcc.withdraw_perequisite, lcc.post_loan_manage, lcc.proposer_user_id, lcc.proposer_employee_assign_id, lcc.proposer_employee_id, lcc.currency, ( SELECT fc.currency_name FROM fnd_currency fc WHERE fc.currency_code = lcc.currency ) currency_n, (select fc.company_short_name from fnd_company fc where fc.company_id = lcc.lon_company_id) lon_company_id_n, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'LON.CREDIT_CATEGORY' and scv.value = lcc.credit_category) credit_category_desc, (select hbmt.bp_name FROM hls_bp_master hbmt where hbmt.bp_id = lcc.ref_credit_bp_id) ref_credit_bp_name, (select min(hcl.valid_from) from hls_credit_line hcl,lon_credit_contract_line lccl where lccl.credit_line_id=hcl.credit_line_id and lccl.credit_contract_id= lcc.credit_contract_id) valid_from, (select max(hcl.valid_to) from hls_credit_line hcl,lon_credit_contract_line lccl where lccl.credit_line_id=hcl.credit_line_id and lccl.credit_contract_id= lcc.credit_contract_id) valid_to, su.description creation_name, hbm.bp_name, hbm.bp_name credit_bp_id_n, hbm.extra_nam, hbm.bp_class, hbm.bp_code, hbm.org_type, v2.meaning org_type_n, hbm.rele_com_flag, v1.meaning rele_com_flag_n, (select cb.bank_name from csh_bank cb where cb.bank_id= hbm.bank_id) bank_name, hbt.description typedes, hbc.description catedes, ( SELECT hdt.description AS description FROM hls_document_type hdt WHERE 1 = 1 AND hdt.document_category = 'LON_CREDIT_CONTRACT' AND hdt.document_type = lcc.document_type ) lon_des, nvl(( select count(1) from lon_contract lc join lon_contract_withdraw lcw on lc.contract_id=lcw.contract_id join lon_credit_contract_line lccl on lccl.credit_line_id= lc.credit_line_id where lc.rele_credit_flag='Y' and lcw.data_class='NORMAL' and lccl.credit_contract_id=lcc.credit_contract_id),0) withdraw_count, (SELECT count(1) FROM hls_credit_line hcl JOIN lon_credit_contract_line lccl ON hcl.credit_line_id=lccl.credit_line_id where lccl.credit_contract_id=lcc.credit_contract_id and hcl.cancel_flag='Y') cancel_count, calc.is_mix FROM lon_credit_contract lcc left join sys_user su on su.user_id=lcc.CREATED_BY, lon_credit_contract_calc calc, hls_bp_master hbm left join SYS_CODE_VALUE_B_V v1 on v1.code = 'SYS.YES_NO' and v1.code_value = hbm.rele_com_flag left join SYS_CODE_VALUE_B_V v2 on v2.code = 'CSH.BANK_ORG_TYPE' and v2.code_value = hbm.org_type, hls_bp_master_role hbmr, hls_bp_type hbt, hls_bp_category hbc
lcc.business_type='LON_CREDIT_CONTRACT' and calc.credit_contract_id=lcc.credit_contract_id AND hbm.bp_id = hbmr.bp_id AND hbm.bp_id = lcc.credit_bp_id AND hbt.bp_type = hbmr.bp_type AND hbc.bp_category = hbmr.bp_category AND hbmr.bp_category = 'CREDIT_ORGANIZATION' AND lcc.company_id = #{request.companyId}
AND lcc.document_type IN
#{item}
AND lcc.credit_category IN
#{item}
AND lcc.currency = #{currencyName}
AND lcc.credit_contract_id = #{creditContractId}
AND (lcc.credit_category = 'EXPOSURE_CREDIT'
OR lcc.credit_category = 'LOW_RISK_CREDIT'
)
AND (lcc.credit_category = 'LOW_RISK_CREDIT'
OR lcc.credit_category = 'EXPOSURE_CREDIT'
)
AND lcc.credit_line_amt <= #{maxAmt}
AND lcc.credit_line_amt >= #{minAmt}
AND ((lcc.credit_line_amt <= #{maxAmt} AND lcc.credit_line_amt >= #{minAmt}) OR lcc.credit_line_amt <= #{amMax})
AND hbm.bp_name like concat(concat('%',#{bpQueryName}),'%')
AND lcc.credit_contract_name like concat(concat('%',#{contractQueryName}),'%')
AND lcc.credit_con_number like concat(concat('%',#{creditConNumber}),'%')
AND ( hbm.bp_name like concat(concat('%',#{bpName}),'%') OR lcc.credit_con_number like concat(concat('%',#{bpName}),'%') OR hbm.extra_nam like concat(concat('%',#{bpName}),'%') )
and credit_bp_id =#{creditBpId}
AND lcc.data_class = #{dataClass}
) TAB
AND TAB.VALID_FROM >= to_date(#{validFromQuery},'YYYY-MM-DD')
AND TAB.VALID_TO <= to_date(#{validToQuery}, 'YYYY-MM-DD')
order by TAB.CREDIT_CON_NUMBER DESC

SELECT lcc.CREDIT_CONTRACT_ID, lcc.COMPANY_ID, lcc.DOCUMENT_TYPE, lcc.DOCUMENT_CATEGORY, lcc.BUSINESS_TYPE, lcc.CREDIT_CONTRACT_NUMBER, lcc.CREDIT_CONTRACT_NAME, lcc.CREDIT_CONTRACT_STATUS, hcl.CREDIT_LINE_ID, lcc.CURRENCY, lcc.CREDIT_BP_ID, lcc.DESCRIPTION, lcc.LON_COMPANY_ID, lcc.FINANCING_CHANNEL, lcc.CREDIT_CON_NUMBER, lcc.CREDIT_REPLY_NO, lccl.CREDIT_CATEGORY, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'LON.CREDIT_CATEGORY' and scv.value = lccl.credit_category) credit_category_desc, lcc.CHANNEL_BUSINESS_FLAG, lcc.REF_CREDIT_BP_ID, lcc.DATA_CLASS, lcc.CONFIRM_STATUS, lcc.LAST_CHANGE_REQ_ID, lcc.withdraw_perequisite, lcc.post_loan_manage, hdt.description AS credit_description , lccl.WITHDRAW_DEADLINE, hcl.credit_line_amt, calc.credit_exposure_amt, calc.withdraw_balance, ( SELECT hbm.bp_name FROM hls_bp_master hbm WHERE hbm.bp_id = lcc.credit_bp_id ) bp_name , hcl.document_type document_type2, calc.actual_available_amt left_amount, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = lcc.ref_credit_bp_id) ref_credit_bp_name, (select hdtt.description from hls_document_type hdtt where hdtt.document_category = 'LON_CREDIT_CONTRACT' and hdtt.document_type = lcc.document_type) document_type_desc, hcl.valid_from, hcl.valid_to, hcl.valid_from valid_from_format, hcl.valid_to valid_to_format, hcl.first_withdraw_date, hcl.delay_from, hcl.delay_to, hcl.competent_dept, hcl.finance_type FROM LON_CREDIT_CONTRACT lcc , LON_CREDIT_CONTRACT_LINE lccl, LON_CREDIT_LINE_CALC calc, hls_credit_line hcl , hls_document_category hdc , hls_document_type hdt
lcc.credit_contract_id=lccl.credit_contract_id and hcl.credit_line_id=lccl.credit_line_id and hcl.credit_line_id=calc.credit_line_id and lcc.data_class = 'NORMAL' and lcc.confirm_status = 'CONFIRMED' AND hdc.document_category = hcl.document_category AND hdc.enabled_flag = 'Y' AND hdt.document_category = hcl.document_category AND hdt.document_type = hcl.document_type AND hdt.business_type = hcl.business_type AND lcc.company_id = #{request.companyId}
AND hcl.cancel_flag ='Y'
AND lcc.credit_contract_id in( select max( lcc.credit_contract_id) from lon_credit_contract lcc group by lcc.credit_bp_id )
AND lcc.credit_bp_id =#{creditBpId}
AND lccl.CREDIT_CATEGORY =#{documentType}
AND lcc.credit_con_number like concat(concat('%',#{creditConNumber}),'%')
AND lcc.credit_contract_name like concat(concat('%',#{creditContractName}),'%')
and EXISTS (select 1 from hls_bp_master hbmt where hbmt.bp_id = lcc.credit_bp_id and hbmt.bp_name like concat(concat('%',#{bpName}),'%'))

select tab.* from ( SELECT lcc.credit_contract_id, YEAR(lcc.LAST_UPDATE_DATE) as credit_year, MONTH(lcc.LAST_UPDATE_DATE) as credit_month, DAY(lcc.LAST_UPDATE_DATE) as credit_day, lcc.credit_category, (select fc.company_full_name from fnd_company fc where fc.company_id=lcc.company_id) as lon_company_id_n, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=lcc.credit_bp_id) as bpName, (select scvb.MEANING from sys_code_b scb,sys_code_value_b scvb where scb.CODE_ID=scvb.CODE_ID and scb.CODE='LON.CREDIT_CATEGORY' and scvb.VALUE=lcc.credit_category) as credit_category_desc, (select hcl.credit_line_amt from hls_credit_line hcl where hcl.credit_line_id=lcc.credit_line_id) as credit_line_amt, nvl((select hcl.credit_exposure_amt from hls_credit_line hcl where hcl.credit_line_id=lcc.credit_line_id),0) as credit_exposure_amt, lc.contract_id, lc.contract_number, (lc.loan_term*(case lc.loan_term_uom when 'MONTH' THEN 1 WHEN 'YEAR' THEN 12 ELSE 1/30 END)) as loan_term, lcw.withdraw_id, lcw.withdraw_number, lcw.due_amount, lc.finance_amount, 0 as par_interest_rate, lcw.consignment_sales_fee_rate, lcw.charge_fee_rate, lcw.consulting_fee_rate, lcw.deposit_rate, lcw.collocation_fee_rate, lcw.management_fee_rate, lcw.other_fee_rate FROM lon_credit_contract lcc, lon_contract lc, lon_contract_withdraw lcw WHERE (( lcc.confirm_status = 'CONFIRMED' AND lcc.data_class = 'NORMAL' ) OR ( lcc.confirm_status = 'PENDING' AND lcc.data_class = 'NORMAL' AND ( SELECT count(*) FROM ct_lon_credit_con_change_req cc WHERE cc.change_req_id = lcc.last_change_req_id and cc.credit_contract_id=lcc.credit_contract_id and cc.req_status='APPROVED' ) > 0 )) and lc.credit_contract_id=lcc.credit_contract_id and lc.credit_line_id = lcc.credit_line_id and lc.contract_id=lcw.contract_id and lc.loan_term is not null ) tab
AND tab.credit_category in
#{item}
AND tab.credit_line_amt >=#{minCreditLineAmt}
AND tab.credit_line_amt <=#{maxCreditLineAmt}
AND tab.finance_amount >=#{minFinanceAmount}
AND tab.finance_amount <=#{maxFinanceAmount}
AND tab.due_amount >=#{minDueAmount}
AND tab.due_amount <=#{maxDueAmount}

mapper.update:
update lon_credit_contract lcc set lcc.credit_exposure_amt = ( select nvl(sum(hcl.credit_exposure_amt),0) from hls_credit_line hcl join lon_credit_contract_line lccl on hcl.credit_line_id=lccl.credit_line_id where lccl.credit_contract_id=lcc.credit_contract_id ) where 1=1
and lcc.credit_contract_id= ( select max(lccl.credit_contract_id) from hls_credit_line hcl join lon_credit_contract_line lccl on hcl.credit_line_id=lccl.credit_line_id where hcl.credit_line_id=#{creditLineId} )
and lcc.credit_contract_id= #{creditContractId}

UPDATE lon_credit_contract lcc SET lcc.credit_unexposure_amt = nvl(lcc.credit_line_amt,0)-nvl( ( CASE ( SELECT COUNT(1) FROM ( SELECT lccl.credit_contract_id, hcl.document_type FROM hls_credit_line hcl JOIN lon_credit_contract_line lccl ON hcl.credit_line_id=lccl.credit_line_id GROUP BY hcl.document_type, lccl.credit_contract_id)cre WHERE cre.credit_contract_id=lcc.credit_contract_id) WHEN 1 THEN ( SELECT nvl(SUM(hcl.credit_exposure_amt),0) FROM hls_credit_line hcl JOIN lon_credit_contract_line lccl ON hcl.credit_line_id=lccl.credit_line_id WHERE lccl.credit_contract_id=lcc.credit_contract_id) ELSE ( SELECT nvl(SUM(hcl.withdraw_balance),0) FROM hls_credit_line hcl JOIN lon_credit_contract_line lccl ON hcl.credit_line_id=lccl.credit_line_id WHERE lccl.credit_contract_id=lcc.credit_contract_id) END),0) WHERE 1=1
and lcc.credit_contract_id= ( SELECT MAX(lccl.credit_contract_id) FROM hls_credit_line hcl JOIN lon_credit_contract_line lccl ON hcl.credit_line_id=lccl.credit_line_id WHERE hcl.credit_line_id=#{creditLineId} )
and lcc.credit_contract_id= #{creditContractId}
